#!/usr/bin/env bash
# Submit single-task online RL manifest as a Slurm array on PACE-ICE.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "${SCRIPT_DIR}/../../.." && pwd)"

MANIFEST=""
GPU_TYPE="H100"
MAX_CONCURRENT=16
TIME_LIMIT="24:00:00"
MEMORY="128G"
CPUS=16
ACCOUNT=""
PARTITION_OVERRIDE=""
QOS="${SLURM_QOS_OVERRIDE:-}"
PYTHON_BIN="python"
CONDA_ENV="${CONDA_ENV_NAME:-}"
DRY_RUN=0

usage() {
  cat <<'EOF'
Usage:
  submit_manifest_array.sh --manifest <path> [options]

Required:
  --manifest PATH              CSV manifest generated by build_manifest.py

Options:
  --gpu-type {H100|H200|A100|L40S}  Target GPU type (default: H100)
  --max-concurrent N           Max concurrent array tasks (default: 16)
  --time HH:MM:SS              Wall clock limit (default: 24:00:00)
  --mem SIZE                   Memory per task (default: 128G)
  --cpus N                     CPUs per task (default: 16)
  --account NAME               Slurm account override
  --partition NAME             Slurm partition override
  --qos NAME                   Optional Slurm QoS (default: cluster default)
  --python-bin PATH            Python executable (default: python)
  --conda-env NAME             Optional conda env to activate before launch
  --dry-run                    Print sbatch command without submitting

Example:
  scripts/experiments/single_task_online/submit_manifest_array.sh \
    --manifest scripts/experiments/single_task_online/manifests/smoke_v1.csv \
    --gpu-type H200 --max-concurrent 12 --time 08:00:00
EOF
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    --manifest) MANIFEST="$2"; shift 2 ;;
    --gpu-type) GPU_TYPE="$(echo "$2" | tr '[:lower:]' '[:upper:]')"; shift 2 ;;
    --max-concurrent) MAX_CONCURRENT="$2"; shift 2 ;;
    --time) TIME_LIMIT="$2"; shift 2 ;;
    --mem) MEMORY="$2"; shift 2 ;;
    --cpus) CPUS="$2"; shift 2 ;;
    --account) ACCOUNT="$2"; shift 2 ;;
    --partition) PARTITION_OVERRIDE="$2"; shift 2 ;;
    --qos) QOS="$2"; shift 2 ;;
    --python-bin) PYTHON_BIN="$2"; shift 2 ;;
    --conda-env) CONDA_ENV="$2"; shift 2 ;;
    --dry-run) DRY_RUN=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) echo "Unknown argument: $1"; usage; exit 1 ;;
  esac
done

if [[ -z "${MANIFEST}" ]]; then
  echo "Error: --manifest is required."
  usage
  exit 1
fi

if [[ ! -f "${MANIFEST}" ]]; then
  echo "Error: manifest not found: ${MANIFEST}"
  exit 1
fi

case "${GPU_TYPE}" in
  H100)
    PARTITION="ice-gpu"
    GRES="gpu:h100:1"
    DEFAULT_ACCOUNT="coc"
    ;;
  H200)
    PARTITION="ice-gpu"
    GRES="gpu:h200:1"
    DEFAULT_ACCOUNT="coc"
    ;;
  A100)
    PARTITION="ice-gpu"
    GRES="gpu:a100:1"
    DEFAULT_ACCOUNT="coc"
    ;;
  L40S)
    PARTITION="ice-gpu"
    GRES="gpu:l40s:1"
    DEFAULT_ACCOUNT="coc"
    ;;
  *)
    echo "Error: unsupported --gpu-type ${GPU_TYPE}. Use H100, H200, A100, or L40S."
    exit 1
    ;;
esac

if [[ -z "${ACCOUNT}" ]]; then
  ACCOUNT="${DEFAULT_ACCOUNT}"
fi
if [[ -n "${PARTITION_OVERRIDE}" ]]; then
  PARTITION="${PARTITION_OVERRIDE}"
fi

NUM_ROWS="$("${PYTHON_BIN}" - <<'PY' "${MANIFEST}"
import csv, sys
with open(sys.argv[1], newline='', encoding='utf-8') as f:
    n = sum(1 for _ in csv.DictReader(f))
print(n)
PY
)"

if [[ "${NUM_ROWS}" -le 0 ]]; then
  echo "Error: manifest has no rows: ${MANIFEST}"
  exit 1
fi

ARRAY_RANGE="0-$((NUM_ROWS - 1))%${MAX_CONCURRENT}"
STAGE_NAME="$("${PYTHON_BIN}" - <<'PY' "${MANIFEST}"
import csv, sys
with open(sys.argv[1], newline='', encoding='utf-8') as f:
    rows = list(csv.DictReader(f))
print(rows[0].get('stage', 'stage'))
PY
)"
JOB_NAME="sto_${STAGE_NAME}_${GPU_TYPE}"
LOG_DIR="${PROJECT_ROOT}/logs/slurm/single_task_online/${STAGE_NAME}"
mkdir -p "${LOG_DIR}"

WRAP_CMD="cd ${PROJECT_ROOT} && source ~/.bashrc"
if [[ -n "${CONDA_ENV}" ]]; then
  WRAP_CMD+=" && conda activate ${CONDA_ENV}"
fi
WRAP_CMD+=" && export PYTHONPATH=${PROJECT_ROOT}/src:\$PYTHONPATH"
WRAP_CMD+=" && export MUJOCO_GL=\${MUJOCO_GL:-egl}"
WRAP_CMD+=" && export PYOPENGL_PLATFORM=\${PYOPENGL_PLATFORM:-egl}"
WRAP_CMD+=" && export EGL_PLATFORM=\${EGL_PLATFORM:-surfaceless}"
WRAP_CMD+=" && export WANDB_DIR=\${WANDB_DIR:-/tmp/${USER}/wandb}"
WRAP_CMD+=" && export WANDB_CACHE_DIR=\${WANDB_CACHE_DIR:-/tmp/${USER}/wandb-cache}"
WRAP_CMD+=" && mkdir -p \$WANDB_DIR \$WANDB_CACHE_DIR"
WRAP_CMD+=" && \$PYTHON_BIN scripts/experiments/single_task_online/run_manifest_job.py"
WRAP_CMD+=" --manifest \$MANIFEST --row-index \$SLURM_ARRAY_TASK_ID"
WRAP_CMD+=" --project-root ${PROJECT_ROOT} --python-bin \$PYTHON_BIN"

SBATCH_CMD=(
  sbatch
  --job-name="${JOB_NAME}"
  --account="${ACCOUNT}"
  --partition="${PARTITION}"
  --gres="${GRES}"
  --nodes=1
  --ntasks=1
  --cpus-per-task="${CPUS}"
  --mem="${MEMORY}"
  --time="${TIME_LIMIT}"
  --array="${ARRAY_RANGE}"
  --output="${LOG_DIR}/${JOB_NAME}_%A_%a.out"
  --error="${LOG_DIR}/${JOB_NAME}_%A_%a.err"
  --export="ALL,PROJECT_ROOT=${PROJECT_ROOT},MANIFEST=${MANIFEST},PYTHON_BIN=${PYTHON_BIN}"
  --wrap="${WRAP_CMD}"
)
if [[ -n "${QOS}" ]]; then
  SBATCH_CMD+=(--qos="${QOS}")
fi

echo "Submitting manifest array:"
echo "  Manifest: ${MANIFEST}"
echo "  Rows: ${NUM_ROWS}"
echo "  GPU: ${GPU_TYPE} (${GRES})"
echo "  Partition: ${PARTITION}"
echo "  Account: ${ACCOUNT}"
if [[ -n "${QOS}" ]]; then
  echo "  QoS: ${QOS}"
fi
if [[ -n "${CONDA_ENV}" ]]; then
  echo "  Conda env: ${CONDA_ENV}"
fi
echo "  Array: ${ARRAY_RANGE}"
echo "  Logs: ${LOG_DIR}"

if [[ "${DRY_RUN}" -eq 1 ]]; then
  printf 'Dry run sbatch command:\n'
  printf ' %q' "${SBATCH_CMD[@]}"
  printf '\n'
  exit 0
fi

"${SBATCH_CMD[@]}"
